    def test_binarize_default_threshold(self):
        # Arrange
        image = np.array([[128, 255], [101, 156]])
        expected_output = np.array([[1, 1], [0, 1]])

        # Act
        result = binarize(image)

        # Assert
        np.testing.assert_array_equal(result, expected_output)

    @pytest.mark.valid
    def test_binarize_custom_threshold(self):
        # Arrange
        image = np.array([[0.07, 1], [0.51, 0.3]])
        custom_threshold = 0.5
        expected_output = np.array([[0, 1], [1, 0]])

        # Act
        result = binarize(image, custom_threshold)

        # Assert
        np.testing.assert_array_equal(result, expected_output)

    @pytest.mark.edge
    def test_binarize_all_values_above_threshold(self):
        # Arrange
        image = np.array([[130, 150], [180, 200]])

        # Act
